// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.automationimport timber.log.Timberimport android.content.Contextimport android.os.Buildimport android.provider.Settings/** * NOUS — Automation Method Detector (Module 9 v1 — Step 9.1). * * Detects the best automation method available on the device using REAL * Android APIs: *  - LADB (Local ADB) — checks Android 11+ + Wireless Debugging enabled *  - AccessibilityService — checks if NOUS service is enabled * * ## Auto-Detection Logic (per strategy v1 §"2-Tier Hybrid") * * ``` * if (Android 11+ && WirelessDebuggingEnabled && LADB connected) → LADB (50x faster) * else if (AccessibilityService enabled) → Accessibility (universal fallback) * else → NONE (user must enable one) * ``` * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§2-Tier Hybrid Architecture</a> */class AutomationMethodDetector(    private val context: Context,) {    companion object {        private const val TAG = "AutomationDetector"        /** Android 11 (API 30) — minimum for Wireless Debugging / LADB. */        const val MIN_API_FOR_LADB = Build.VERSION_CODES.R    }    /**     * Detect the best automation method available (REAL Android API checks).     *     * @return the best available [AutomationMethod], or [AutomationMethod.NONE].     */    fun detectBestMethod(): AutomationMethod {        // Check LADB first (faster).        if (isLadbSupported() && isWirelessDebuggingEnabled()) {            Timber.tag(TAG).i("Best method: LADB (Android ${Build.VERSION.SDK_INT} + Wireless Debugging).")            return AutomationMethod.LADB        }        // Check Accessibility (universal fallback).        if (isAccessibilityEnabled()) {            Timber.tag(TAG).i("Best method: AccessibilityService (LADB not available).")            return AutomationMethod.ACCESSIBILITY        }        // Neither available — user must enable one.        Timber.tag(TAG).w("No automation method available. User must enable Accessibility or Wireless Debugging.")        return AutomationMethod.NONE    }    /**     * Check if the device supports LADB (Android 11+).     *     * LADB requires Wireless Debugging which was introduced in Android 11 (API 30).     *     * @return true if the device API level supports LADB.     */    fun isLadbSupported(): Boolean {        val supported = Build.VERSION.SDK_INT >= MIN_API_FOR_LADB        Timber.tag(TAG).d("LADB supported: $supported (API ${Build.VERSION.SDK_INT} >= $MIN_API_FOR_LADB).")        return supported    }    /**     * Check if Wireless Debugging is enabled (REAL Android API).     *     * On Android 11+, Wireless Debugging is controlled via Developer Options.     * The setting is stored in [Settings.Global.ADB_WIFI_ENABLED] (API 30+).     *     * Note: This setting may not be readable on all devices (some OEMs restrict it).     * In that case, we fall back to attempting a connection + treating failure as "not enabled".     *     * @return true if Wireless Debugging appears to be enabled.     */    fun isWirelessDebuggingEnabled(): Boolean {        if (Build.VERSION.SDK_INT < MIN_API_FOR_LADB) return false        return try {            // On Android 11+, the setting is "adb_wifi_enabled" in Settings.Global.            // Note: This is a hidden API — we use the string literal.            val enabled = Settings.Global.getInt(                context.contentResolver,                "adb_wifi_enabled",                0,            )            Timber.tag(TAG).d("Wireless Debugging enabled: ${enabled == 1}.")            enabled == 1        } catch (e: Exception) {            // Some devices restrict access to this setting.            // In that case, we can't detect it — return false + let the user manually connect.            Timber.tag(TAG).w("Cannot read Wireless Debugging setting — assuming disabled.", e)            false        }    }    /**     * Check if the NOUS AccessibilityService is enabled (REAL Android API).     *     * Delegates to [com.roshan.persona.agent.permission.AccessibilityPermissionManager].     *     * @return true if the accessibility service is enabled.     */    fun isAccessibilityEnabled(): Boolean {        val pm = com.roshan.persona.agent.permission.AccessibilityPermissionManager(context)        return pm.isAccessibilityEnabled()    }    /**     * Get the full availability report (for Settings → Debug → Automation).     */    fun getAvailabilityReport(): AutomationAvailabilityReport {        return AutomationAvailabilityReport(            ladbSupported = isLadbSupported(),            wirelessDebuggingEnabled = isWirelessDebuggingEnabled(),            accessibilityEnabled = isAccessibilityEnabled(),            bestMethod = detectBestMethod(),            androidApiLevel = Build.VERSION.SDK_INT,            androidVersion = Build.VERSION.RELEASE,        )    }    /**     * Get the user-facing message for the current automation state.     */    fun getUserMessage(): String = when (detectBestMethod()) {        AutomationMethod.LADB -> "Fast automation mode (LADB). Actions complete in 10ms."        AutomationMethod.ACCESSIBILITY -> "Standard automation mode. Actions complete in 200-500ms."        AutomationMethod.NONE -> """            No automation method available.            To enable fast mode: Settings → Developer Options → Wireless Debugging → Enable.            To enable standard mode: Settings → Accessibility → NOUS → Enable.        """.trimIndent()    }}// ──────────────────────────────────────────────────────────────────────────/** Available automation methods (2-tier hybrid). */enum class AutomationMethod(val displayName: String, val speedMs: Long) {    /** LADB (Local ADB) — 10ms per action, Android 11+ only. */    LADB("LADB (Fast)", 10),    /** AccessibilityService — 200-500ms per action, all Android versions. */    ACCESSIBILITY("AccessibilityService (Standard)", 500),    /** No automation method available. */    NONE("None", 0);    /** True if this method is available (not NONE). */    val isAvailable: Boolean get() = this != NONE    /** True if this is the fast tier (LADB). */    val isFastTier: Boolean get() = this == LADB}/** Full availability report (for Settings → Debug → Automation). */data class AutomationAvailabilityReport(    val ladbSupported: Boolean,    val wirelessDebuggingEnabled: Boolean,    val accessibilityEnabled: Boolean,    val bestMethod: AutomationMethod,    val androidApiLevel: Int,    val androidVersion: String,) {    /** True if LADB is fully available (supported + enabled). */    val ladbAvailable: Boolean get() = ladbSupported && wirelessDebuggingEnabled    /** True if at least one method is available. */    val anyMethodAvailable: Boolean get() = bestMethod.isAvailable    /** Human-readable summary. */    val summary: String        get() = """            Automation Status:            • Best method: ${bestMethod.displayName}            • LADB: ${if (ladbAvailable) "Available" else if (ladbSupported) "Supported but Wireless Debugging not enabled" else "Not supported (Android ${androidVersion})"}            • Accessibility: ${if (accessibilityEnabled) "Enabled" else "Not enabled"}            • Android: $androidVersion (API $androidApiLevel)        """.trimIndent()}